const form=document.getElementById("avgForm"),result=document.getElementById("result");form&&form.addEventListener("submit",t=>{t.preventDefault();const s=parseFloat(document.getElementById("income").value)||0,a=parseInt(document.getElementById("days").value,10)||0,l=parseInt(document.getElementById("tenure").value,10)||100,e=parseInt(document.getElementById("sickDays").value,10)||0;if(s<=0||a<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите доход и число дней больше нуля.</p>';return}const n=s/a,i=n*30.4,c=e>0?n*e*(l/100):0;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Средний дневной</span><span class="val">${fmt(n)} ₽</span></div>
        <div class="item"><span>Средний месячный</span><span class="val">${fmt(i)} ₽</span></div>
        ${e>0?`<div class="item"><span>Пособие за ${e} дн. (${l}%)</span><span class="val">${fmt(c)} ₽</span></div>`:""}
      </div>
      <p class="hint" style="margin-top:14px">Расчёт ориентировочный; для точных пособий учитывайте лимиты и исключаемые дни.</p>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(t)}
